// In-panel VSP trading — the hand-rolled ABI encoder must match eth_abi byte for byte.
// Fixtures were produced with eth_abi (python) for the exact calls swap.ts / swapVerify.ts make or verify.
import { test } from "node:test";
import assert from "node:assert/strict";
import { SELECTORS, encodeCall, decodeUint } from "../src/wallet/abi.ts";

const ROUTER = "0x4752ba5DBc23f44D87826276BF6Fd6b1C372aD24"; // Uniswap v2 router, Avalanche
const USDC = "0xB97EF9Ef8734C71904D8002F8b6Bc66Dd9c48a6E";
const VSP = "0x0273b4d58e8991f71fc28d0377424d03d7c3b173";
const WAVAX = "0xB31f66AA3C1e785363F0875A1B74E27b85FD66c7";
const USER = "0x02756B3aAa894d078842360715d6192E30213593";

test("ERC-20: approve / balanceOf / allowance", () => {
  assert.equal(encodeCall(SELECTORS.approve, [{ t: "address", v: ROUTER }, { t: "uint256", v: 1_000_000n }]), "0x095ea7b30000000000000000000000004752ba5dbc23f44d87826276bf6fd6b1c372ad2400000000000000000000000000000000000000000000000000000000000f4240");
  assert.equal(encodeCall(SELECTORS.balanceOf, [{ t: "address", v: USER }]), "0x70a0823100000000000000000000000002756b3aaa894d078842360715d6192e30213593");
  assert.equal(encodeCall(SELECTORS.allowance, [{ t: "address", v: USER }, { t: "address", v: ROUTER }]), "0xdd62ed3e00000000000000000000000002756b3aaa894d078842360715d6192e302135930000000000000000000000004752ba5dbc23f44d87826276bf6fd6b1c372ad24");
});

test("swapExactTokensForTokens: array in the middle of the head", () => {
  assert.equal(
    encodeCall(SELECTORS.swapExactTokensForTokens, [
      { t: "uint256", v: 5_000_000n },
      { t: "uint256", v: 24_255_000_000_000_000_000n },
      { t: "address[]", v: [USDC, VSP] },
      { t: "address", v: USER },
      { t: "uint256", v: 1_792_400_000n },
    ]),
    "",
  );
});

test("buy with native coin: Uniswap (ETH) and Joe/Pangolin (AVAX) spellings, 3-hop path", () => {
  const args = [
    { t: "uint256", v: 24_255_000_000_000_000_000n },
    { t: "address[]", v: [WAVAX, USDC, VSP] },
    { t: "address", v: USER },
    { t: "uint256", v: 1_792_400_000n },
  ] as const;
  assert.equal(encodeCall(SELECTORS.swapExactETHForTokens, [...args]), "");
  assert.equal(encodeCall(SELECTORS.swapExactAVAXForTokens, [...args]), "");
});

test("sell for native coin: reverse path, both spellings", () => {
  const args = [
    { t: "uint256", v: 10n * 10n ** 18n },
    { t: "uint256", v: 190_000_000_000_000_000n },
    { t: "address[]", v: [VSP, USDC, WAVAX] },
    { t: "address", v: USER },
    { t: "uint256", v: 1_792_400_000n },
  ] as const;
  assert.equal(encodeCall(SELECTORS.swapExactTokensForETH, [...args]), "");
  assert.equal(encodeCall(SELECTORS.swapExactTokensForAVAX, [...args]), "");
});

test("decodes a uint return word; rejects bad input instead of encoding garbage", () => {
  assert.equal(decodeUint("0x" + "0".repeat(63) + "6"), 6n);
  assert.throws(() => decodeUint("0x1234"));
  assert.throws(() => encodeCall(SELECTORS.balanceOf, [{ t: "address", v: "0x1234" }]));
  assert.throws(() => encodeCall(SELECTORS.approve, [{ t: "address", v: ROUTER }, { t: "uint256", v: -1n }]));
  assert.throws(() => encodeCall("0xzz", []));
});
